import type { MetadataRoute } from "next";

import { APP_DESCRIPTION, APP_NAME, APP_SHORT_NAME, BACKGROUND_COLOR, THEME_COLOR } from "@/lib/pwa";

/**
 * Web app manifest. Icons are generated by /api/pwa-icon so a rebrand only ever
 * touches one file, and the app is installable on Android/Chrome, Windows and
 * iOS (Share → Add to Home Screen).
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: `${APP_NAME} — Uganda airplay`,
    short_name: APP_SHORT_NAME,
    description: APP_DESCRIPTION,
    id: "/",
    start_url: "/?source=pwa",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: BACKGROUND_COLOR,
    theme_color: THEME_COLOR,
    categories: ["music", "business", "productivity"],
    icons: [
      { src: "/api/pwa-icon?size=192", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/api/pwa-icon?size=512", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/api/pwa-icon?size=512&maskable=1", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
    shortcuts: [
      { name: "Live charts", short_name: "Charts", url: "/#charts" },
      { name: "My dashboard", short_name: "Dashboard", url: "/dashboard" },
      { name: "Coverage", short_name: "Coverage", url: "/coverage" },
    ],
  };
}
